## Code Example
```javascript
const Ajv = require('ajv');
const ajv = new Ajv({allErrors: true});
// imagine fetching versioned schema from registry
const schemas = { v1: { type: 'object', properties: { user_id: {type:'string'}, email: {type:'string', format:'email'} }, required: ['user_id'] } };
